  package      org . sonar . plugins . web . checks . sonar ;   import    org . sonar . check . Rule ;  import      org . sonar . plugins . web . checks . AbstractPageCheck ;  import      org . sonar . plugins . web . node . TagNode ;    @ Rule  (  key = "BoldAndItalicTagsCheck" ) public class BoldAndItalicTagsCheck  extends AbstractPageCheck  {    @ Override public void startElement  (  TagNode node )  {  if  (  isBold  ( node ) )  {   createViolation  (  node . getStartLinePosition  ( ) ,   "Replace this <" +  node . getNodeName  ( ) + "> tag by <strong>." ) ; } else  if  (  isItalicAndNotAriaHidden  ( node ) )  {   createViolation  (  node . getStartLinePosition  ( ) ,   "Replace this <" +  node . getNodeName  ( ) + "> tag by <em>." ) ; } }   private static boolean isBold  (  TagNode node )  {  return  "B" . equalsIgnoreCase  (  node . getNodeName  ( ) ) ; }   private static boolean isItalicAndNotAriaHidden  (  TagNode node )  {  return   "I" . equalsIgnoreCase  (  node . getNodeName  ( ) ) &&  !  "true" . equalsIgnoreCase  (  node . getAttribute  ( "aria-hidden" ) ) ; } }